import{_ as t,c as o,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Shortcode Element","description":"Shortcode Element","frontmatter":{"title":"Shortcode Element","description":"Shortcode Element"},"headers":[],"relativePath":"guide/drag-drop-elements/shortcode-element.md","filePath":"guide/drag-drop-elements/shortcode-element.md"}'),a={name:"guide/drag-drop-elements/shortcode-element.md"};function s(d,e,l,i,h,c){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="shortcode-element" tabindex="-1">Shortcode Element <a class="header-anchor" href="#shortcode-element" aria-label="Permalink to &quot;Shortcode Element&quot;">​</a></h1><p>Shortcodes are codes within brackets with just a few words that allow you to execute complex codes and generate content from a single line that normally requires a lot of complex codes. Even though a shortcode looks like a single line of text, this will not work in a Text element. That’s why Ninja Tables offers a free shortcode element separately to let you add your shortcode to the table. Let’s add a Shortcode element to Ninja Tables.</p><h2 id="properties-of-shortcode-element" tabindex="-1"><strong>Properties of Shortcode Element</strong> <a class="header-anchor" href="#properties-of-shortcode-element" aria-label="Permalink to &quot;**Properties of Shortcode Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>Shortcode Box</td><td>Text Editor Box</td></tr><tr><td>Alignment</td><td>Left, Center, and Right</td></tr><tr><td><img src="https://ninjatables.com/wp-content/uploads/2023/08/Fluent-Forms-shortcode-1024x369.png" alt="Fluent Forms shortcode"></td><td></td></tr></tbody></table><ul><li><strong>Shortcode Box:</strong> Place your shortcode inside this field. In the example, we used a Fluent Forms shortcode for an Email Submission form.</li><li><strong>Alignment:</strong> You can align the shortcode-generated content on either the Left, Center, or Right side of the cell. This is how the above shortcode generates content inside the table: <img src="https://ninjatables.com/wp-content/uploads/2023/08/Screenshot-2023-08-28-at-12.34.34-PM-1024x326.png" alt="Fluent Forms in table"></li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>Adding a shortcode element in tables can display any shortcode-generated content you want. And drag and drop data table is a lot more flexible in this feature. Paste any shortcode and showcase the table smartly. Let us know your thoughts and questions in the comment box.</p>',7)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
